codeExamples.code:
// Write must be acknowledged by a majority of replica-set members
db.accounts.updateOne(
  { _id: 'acct-123' },
  { $inc: { balance: -100 } },
  { writeConcern: { w: 'majority', wtimeout: 5000 } }
);

// Linearizable read: returns the most recent majority-acknowledged value
db.accounts.find(
  { _id: 'acct-123' }
).readConcern('linearizable').maxTimeMS(5000);

// During a partition, the minority side cannot reach majority -> write times out (CP: chooses consistency over availability)
